const { MongoClient } = require('mongodb');
const uri = $env.MONGODB_URI;
if (!uri) throw new Error('MONGODB_URI is not set');
const client = new MongoClient(uri);
await client.connect();
const rows = [];
try {
  const db = client.db($env.MONGODB_DB || 'automation_hub');
  const docs = await db.collection('trading_leads').find({}).sort({ updated_at: -1 }).limit(500).toArray();
  for (const d of docs) {
    rows.push({
      updated_at: d.updated_at ? new Date(d.updated_at).toISOString() : '',
      discord_user_id: String(d.discord_user_id || ''),
      discord_username: String(d.discord_username || ''),
      full_name: String(d.full_name || ''),
      email: String(d.email || ''),
      phone: String(d.phone_e164 || d.phone || ''),
      tier: String(d.tier || ''),
      status: String(d.status || ''),
      in_community: String(Boolean(d.in_community)),
      plan_id: String(d.plan_id || ''),
      amount_usd: Number(d.amount_usd || 0),
      roles: Array.isArray(d.roles) ? d.roles.join(',') : '',
      whop_payment_id: String(d.whop_payment_id || ''),
      source: String(d.source || 'vps_n8n'),
      live_link: String(d.discord_live_url || d.unique_zoom_url || ''),
      notes: String(d.country || '') + ' | ' + String(d.trading_level || '')
    });
  }
} finally {
  await client.close();
}
return [{ json: { ok: true, gsheet_id: 'YOUR_GOOGLE_ID', row_count: rows.length, rows } }];
